//! The rendering mode and the advances of the DirectWrite backend at a device pixel ratio of 1,
//! against real Qt 6.12 on Windows (`tests/data/directwrite_modes_golden.txt`, regenerated by
//! `tests/data/gen_directwrite_modes_golden.py`).
//!
//! What this pins (Qt 6.12: `qwindowsfontenginedirectwrite.cpp` `useSymmetricAntialiasing`,
//! `hintingPreferenceToRenderingMode`, `recalcAdvances`; `qfontengine.cpp` `hasHinting`):
//! * the rendering mode is `NATURAL_SYMMETRIC` for a size over 16 px or a font whose `maxp` table
//!   announces no hinting instructions, `GDI_CLASSIC` otherwise, and the first `gasp` range whose
//!   `rangeMaxPPEM` reaches the size overrides that with its symmetric smoothing bit (0x8): the
//!   glyph bitmaps and whole strings of three synthetic fonts that differ only in those tables
//!   (`oracle_text.ttf`, `oracle_text_hinted.ttf`, `oracle_text_gasp.ttf`) at 8 to 24 px;
//! * the advances are `GetGdiCompatibleGlyphMetrics` with `needsNaturalMetrics` for the natural
//!   modes, `DESIGN_TO_LOGICAL`, and rounded once after the shaper added its kerning: the string
//!   advances (`QFontMetricsF::horizontalAdvance`) of the fixtures and of Windows system fonts
//!   (Arial, Arial Bold, Arial Italic, Segoe UI, Calibri, Consolas, Tahoma) at 8 to 24 px, and the
//!   glyph bitmaps of those fonts at the sizes where their `gasp` tables change the mode.
//!
//! The system fonts are compared only when the file on this machine is the one the golden was
//! measured with (size and hash in the golden), so another Windows build skips them instead of
//! failing; the fixtures are in the repository and always run.
#![cfg(windows)]

use ferrokit_gui::geometry::primitives::PointF;
use ferrokit_gui::paint::{Painter, Pen, Pixmap};
use ferrokit_gui::text::directwrite_face::is_available;
use ferrokit_gui::text::font::{Font, FontStyle, FontWeight, SharedFontData};
use ferrokit_gui::text::font_database::resolve_font_engines_for_text_global;
use ferrokit_gui::text::font_metrics::FontMetrics;
use ferrokit_gui::text::smoothing::TextSmoothing;
use ferrokit_gui::tiny_skia::Color;

const GOLDEN: &str = include_str!("data/directwrite_modes_golden.txt");
const TEXT_A: &str = "Hello Wor-ld 0123 AVTo";
const TEXT_B: &str = "ACEFHJKMOPRTUWY";
const SYS_GLYPH_TEXT: &str = "Hamburgefonts 0123";

fn fixture(family: &str) -> &'static [u8] {
    match family {
        "FerrokitOracleText" => include_bytes!("data/oracle_text.ttf"),
        "FerrokitOracleHinted" => include_bytes!("data/oracle_text_hinted.ttf"),
        "FerrokitOracleGasp" => include_bytes!("data/oracle_text_gasp.ttf"),
        other => panic!("no fixture font {other}"),
    }
}

fn fnv1a64(data: &[u8]) -> u64 {
    data.iter().fold(0xcbf2_9ce4_8422_2325u64, |h, &b| {
        (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3)
    })
}

fn sys_text(id: &str) -> &'static str {
    match id {
        "a" => "Hello, World 123 AVAWTo",
        "b" => "The quick brown fox jumps over the lazy dog",
        "c" => "WWWWW iiiii fi fl ffi 0123456789",
        other => panic!("no text {other}"),
    }
}

/// Family, weight, italic of a system font file of the golden.
fn sys_font(file: &str, px: u32) -> Font {
    let (family, bold, italic) = match file {
        "arial.ttf" => ("Arial", false, false),
        "arialbd.ttf" => ("Arial", true, false),
        "ariali.ttf" => ("Arial", false, true),
        "segoeui.ttf" => ("Segoe UI", false, false),
        "calibri.ttf" => ("Calibri", false, false),
        "consola.ttf" => ("Consolas", false, false),
        "tahoma.ttf" => ("Tahoma", false, false),
        other => panic!("no system font {other}"),
    };
    let mut font = Font::new(family, px as f32);
    if bold {
        font = font.with_weight(FontWeight::Bold);
    }
    if italic {
        font = font.with_style(FontStyle::Italic);
    }
    font
}

fn fixture_font(family: &str, px: u32) -> Font {
    Font::new(family, px as f32).with_font_data(SharedFontData::from_vec(fixture(family).to_vec()))
}

/// `QFontMetricsF::horizontalAdvance` in 1/64 px.
fn advance64(font: &Font, text: &str) -> i64 {
    let advance = FontMetrics::from_font(font).horizontal_advance_exact(text, font);
    let fixed = f64::from(advance) * 64.0;
    assert_eq!(
        fixed,
        fixed.round(),
        "{text:?} is not a whole number of 1/64 px"
    );
    fixed as i64
}

/// Width, height and A8 bytes of every distinct character of `text`, in order, hashed.
fn glyph_hash(font: &Font, text: &str) -> u64 {
    let engines = resolve_font_engines_for_text_global(font, text);
    let face = &engines[0].face;
    let mut seen = Vec::new();
    let mut blob = Vec::new();
    for ch in text.chars() {
        if seen.contains(&ch) {
            continue;
        }
        seen.push(ch);
        let (metrics, bits) = face.rasterize_scaled(face.glyph_index(ch), font.size, 1.0);
        blob.extend_from_slice(&(metrics.width as u16).to_le_bytes());
        blob.extend_from_slice(&(metrics.height as u16).to_le_bytes());
        if metrics.width > 0 && metrics.height > 0 {
            assert_eq!(bits.len(), metrics.width * metrics.height);
            blob.extend_from_slice(&bits);
        }
    }
    fnv1a64(&blob)
}

/// `QPainter::drawText` of `TEXT_A` with a black pen on white, ClearType, as the golden's.
fn draw(font: &Font, px: u32) -> (u32, u32, u64) {
    let (w, h) = (320, px * 2 + 12);
    let mut pixmap = Pixmap::with_dpr(w, h, 1.0).expect("pixmap");
    pixmap.fill(Color::from_rgba8(255, 255, 255, 255));
    {
        let mut painter = Painter::begin(&mut pixmap);
        painter.set_text_smoothing(TextSmoothing {
            cleartype: true,
            gamma: 1.2,
        });
        painter.set_pen(Some(Pen::new(Color::from_rgba8(0, 0, 0, 255), 1.0)));
        painter.draw_text(PointF::new(6.0, px as f32 + 6.0), TEXT_A, font);
    }
    (
        pixmap.physical_width(),
        pixmap.physical_height(),
        fnv1a64(pixmap.data()),
    )
}

fn hex(field: &str) -> u64 {
    u64::from_str_radix(field, 16).expect("hash")
}

/// Compares one golden line; `Err` carries the report of a difference.
fn check(fields: &[&str], system_font: Option<&str>) -> Result<(), String> {
    let int = |s: &str| s.parse::<u32>().expect("number");
    match (fields[0], system_font) {
        ("adv", None) => {
            let font = fixture_font(fields[1], int(fields[2]));
            let text = if fields[3] == "a" { TEXT_A } else { TEXT_B };
            let (got, want) = (advance64(&font, text), fields[4].parse::<i64>().unwrap());
            (got == want).then_some(()).ok_or(format!(
                "advance {} {} px {}: {got}/64, Qt {want}/64",
                fields[1], fields[2], fields[3]
            ))
        }
        ("glyphs", None) => {
            let font = fixture_font(fields[1], int(fields[2]));
            let (got, want) = (glyph_hash(&font, TEXT_A), hex(fields[3]));
            (got == want).then_some(()).ok_or(format!(
                "glyph bitmaps {} {} px: {got:016x}, Qt {want:016x}",
                fields[1], fields[2]
            ))
        }
        ("draw", None) => {
            let px = int(fields[2]);
            let font = fixture_font(fields[1], px);
            let (w, h, got) = draw(&font, px);
            let want = (int(fields[3]), int(fields[4]), hex(fields[5]));
            ((w, h, got) == want).then_some(()).ok_or(format!(
                "string {} {px} px: {got:016x}, Qt {:016x}",
                fields[1], want.2
            ))
        }
        ("sysadv", Some(file)) => {
            let font = sys_font(file, int(fields[2]));
            let (got, want) = (
                advance64(&font, sys_text(fields[3])),
                fields[4].parse::<i64>().unwrap(),
            );
            (got == want).then_some(()).ok_or(format!(
                "advance {file} {} px text {}: {got}/64, Qt {want}/64",
                fields[2], fields[3]
            ))
        }
        ("sysglyphs", Some(file)) => {
            let font = sys_font(file, int(fields[2]));
            let (got, want) = (glyph_hash(&font, SYS_GLYPH_TEXT), hex(fields[3]));
            (got == want).then_some(()).ok_or(format!(
                "glyph bitmaps {file} {} px: {got:016x}, Qt {want:016x}",
                fields[2]
            ))
        }
        _ => panic!("golden line {fields:?}"),
    }
}

/// Runs the golden lines of `kind`: the fixtures' (`system == false`) or those of the system fonts
/// that are on this machine unchanged. Returns (compared, failures).
fn run_golden(system: bool) -> (usize, Vec<String>) {
    let mut compared = 0;
    let mut failures = Vec::new();
    let mut current: Option<String> = None;
    for line in GOLDEN
        .lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
    {
        let fields: Vec<&str> = line.split(' ').collect();
        if fields[0] == "sysfont" {
            let (size, hash) = (fields[2].parse::<usize>().unwrap(), hex(fields[3]));
            let dir = std::env::var("WINDIR").unwrap_or_else(|_| "C:/Windows".to_string());
            current = std::fs::read(format!("{dir}/Fonts/{}", fields[1]))
                .ok()
                .filter(|bytes| bytes.len() == size && fnv1a64(bytes) == hash)
                .map(|_| fields[1].to_string());
            if system && current.is_none() {
                eprintln!("skipping {}: not installed as measured", fields[1]);
            }
            continue;
        }
        let is_system = fields[0].starts_with("sys");
        if is_system != system || (system && current.is_none()) {
            continue;
        }
        compared += 1;
        if let Err(report) = check(&fields, current.as_deref().filter(|_| system)) {
            failures.push(report);
        }
    }
    (compared, failures)
}

#[test]
fn fixture_fonts_pick_the_rendering_mode_and_advances_of_qt() {
    // DirectWrite's in-memory loader needs Windows 10 1703; on an older system the crate draws
    // with its outline backend, which these goldens do not describe.
    if !is_available() {
        return;
    }
    let (compared, failures) = run_golden(false);
    assert_eq!(compared, 3 * 17 * 4, "golden lines of the fixtures");
    assert!(
        failures.is_empty(),
        "{} of {compared} differ from Qt:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn system_fonts_pick_the_rendering_mode_and_advances_of_qt() {
    if !is_available() {
        return;
    }
    let (compared, failures) = run_golden(true);
    assert!(
        failures.is_empty(),
        "{} of {compared} differ from Qt:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
